#!/usr/bin/env node
/**
 * Write the vendor application's configuration out as Dart.
 *
 *   node tools/build-vendor-config.mjs
 *
 * Three facts, from the two places that already hold them: the project address
 * and its publishable key come from `supabase/project.json`, and the vendor's
 * own email address comes from the environment. All three are compiled into
 * the application rather than typed into it, because the vendor should open
 * their licence console and be asked for a password — not for an address, a
 * key, and which account they are.
 *
 * The generated file is not committed. The address and the key are public by
 * design, but an email address in a public repository is an email address in a
 * public repository, and there is no reason for it to be there.
 */

import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const project = JSON.parse(readFileSync(resolve('supabase/project.json'), 'utf8'));
const email = (process.env.QSERVE_VENDOR_EMAIL ?? '').trim();

if (!email) {
  process.stdout.write(
    '\n  ! no QSERVE_VENDOR_EMAIL — this build will have no account to sign in\n'
    + '    as, so the password screen will refuse every password.\n\n',
  );
}

const out = resolve(process.argv[2] ?? 'apps/vendor/lib/config.dart');
const dart = `// GENERATED by tools/build-vendor-config.mjs — do not edit, do not commit.
//
// Where this build talks, the key it opens the conversation with, and whose
// account it signs in as. The key is the publishable one: on its own it opens
// nothing, because every table is behind row level security and access needs
// an account named in vendor_admins.

const String projectUrl = ${JSON.stringify(project.url)};
const String anonKey = ${JSON.stringify(project.anonKey)};
const String vendorEmail = ${JSON.stringify(email)};
`;

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, dart);
console.log(`vendor config -> ${out}${email ? ` (${email})` : ' (no account)'}`);
